<?php
$report=$_GET['report']??'inventory';$allowed=['inventory','availability','active','overdue','history','condition'];if(!in_array($report,$allowed,true))redirect('?page=reports');
$from=$_GET['from']??'';$to=$_GET['to']??'';$category=(int)($_GET['category']??0);
$headers=['inventory'=>['Equipment','Category','Asset ID','Condition','Status'],'condition'=>['Equipment','Category','Asset ID','Condition','Status'],'availability'=>['Category','Total','Available','On loan','Awaiting inspection','Under repair'],'active'=>['Borrower','Equipment','Asset ID','Issued','Due'],'overdue'=>['Borrower','Equipment','Asset ID','Issued','Due','Days overdue'],'history'=>['Borrower','Equipment','Asset ID','Issued','Due','Returned','Return condition']];
$base="SELECT e.name,c.name,i.asset_code,i.condition_label,i.status FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id JOIN equipment_categories c ON c.id=e.category_id";
if(in_array($report,['inventory','condition'],true)){$sql=$base.' WHERE (?=0 OR c.id=?) ORDER BY c.name,e.name';$args=[$category,$category];}
elseif($report==='availability'){$sql="SELECT c.name,COUNT(i.id),SUM(i.status='Available'),SUM(i.status='On Loan'),SUM(i.status='Awaiting Inspection'),SUM(i.status='Under Repair') FROM equipment_categories c LEFT JOIN equipment e ON e.category_id=c.id LEFT JOIN equipment_items i ON i.equipment_id=e.id GROUP BY c.id ORDER BY c.name";$args=[];}
else{$sql="SELECT b.full_name,e.name,i.asset_code,l.issued_at,l.due_date".($report==='overdue'?',DATEDIFF(CURDATE(),l.due_date)':'').($report==='history'?',l.returned_at,l.return_condition':'')." FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id WHERE 1=1";$args=[];if($report==='active')$sql.=' AND l.returned_at IS NULL';if($report==='overdue')$sql.=' AND l.returned_at IS NULL AND l.due_date<CURDATE()';if($report==='active'||$report==='overdue'||$report==='history'){if($from!==''){$sql.=' AND '.($report==='overdue'?'l.due_date':'l.issued_at').'>=?';$args[]=$from;}if($to!==''){$sql.=' AND '.($report==='overdue'?'l.due_date':'l.issued_at').'<=?';$args[]=$to;}}$sql.=' ORDER BY l.due_date';}
$stmt=$pdo->prepare($sql);$stmt->execute($args);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="careshare-'.$report.'-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,$headers[$report]);while($row=$stmt->fetch(PDO::FETCH_NUM)){foreach($row as &$value){$value=(string)($value??'');if(preg_match('/^[=+@\-\t\r]/',$value))$value="'".$value;}unset($value);fputcsv($out,$row);}fclose($out);exit;
